"""Writing the parsed template as `questionnaire/forms/fl_blue_51_data.py` (G124). Pure.

Deterministic: dicts are emitted in sorted key order and the file is always LF-terminated, so regenerating from the
same template gives a byte-identical module (the command runs in the Linux container).
"""

HEADER = (
    '"""Florida Blue 51+ Underwriting Questionnaire — extracted carrier data (G124). A data module, exempt from the 300-line\n'  # noqa: E501
    'rule (rule 8).\n'
    '\n'
    'GENERATED by `manage.py extract_questionnaire_spec` (questionnaire/management/commands; a dev command, never run by\n'  # noqa: E501
    'the app) — DO NOT EDIT BY HAND. Regenerate with:\n'
    '\n'
    '    python manage.py extract_questionnaire_spec --template assets/questionnaires/fl_blue_51_uw_v9.template.xml\n'
    '\n'
    "The source of truth is the template packet of the carrier's XFA original, committed as\n"
    '`assets/questionnaires/fl_blue_51_uw_v9.template.xml`; `SOURCE_SHA256` is its hash, and the start-up check\n'
    '(`questionnaire/checks.py`) fails loudly when the bundled template no longer matches it. Ported unchanged from old\n'  # noqa: E501
    'Vantage 891f1b3 (`benefits/questionnaires/fl_blue_51_data.py`). The presentation spec (layout, labels, legal copy,\n'  # noqa: E501
    'aliases) lives next door in `fl_blue_51.py`; this module is data only.\n'
    '"""\n'
    '\n'
)

NL, CR = chr(10), chr(13)

# Emission order: the hash first, then the tables, the largest last.
EMIT_ORDER = [
    'SOURCE_SHA256',
    'CONDITION_OVERRIDES',
    'MED_CATEGORIES',
    'CATEGORY_LEGEND',
    'CATEGORY_EFFECTS',
    'CONDITIONS_BY_CATEGORY',
    'CONDITION_EFFECTS',
    'DETAILS_BY_CONDITION',
    'CAPTIONS',
    'SIC_CODES',
]


def py(value, indent=0):
    """A value as Python source: one item per line, dicts in sorted key order, tuples on one line."""
    pad, inner = ' ' * indent, ' ' * (indent + 4)
    if isinstance(value, dict):
        if not value:
            return '{}'
        rows = [f'{inner}{key!r}: {py(value[key], indent + 4)},' for key in sorted(value)]
        return NL.join(['{', *rows, pad + '}'])
    if isinstance(value, tuple):
        return '(' + ', '.join(repr(v) for v in value) + ')'
    if isinstance(value, list):
        if not value:
            return '[]'
        return NL.join(['[', *[f'{inner}{py(item, indent + 4)},' for item in value], pad + ']'])
    return repr(value)


def render_data_module(parsed):
    """The data module's source text."""
    chunks = [HEADER, *[f'{name} = {py(parsed[name])}' + NL for name in EMIT_ORDER]]
    return NL.join(chunks).replace(CR + NL, NL)
